#!/usr/bin/env node
// KEYSTONE live integration check. Run on a machine WITH internet after `npm install`:
//   npm run verify:live                      (libauth + nostr-tools + SQLite; relay stage SKIPPED)
//   LIVE_RELAYS=wss://relay.damus.io,wss://nos.lol npm run verify:live
// Uses the PRODUCTION code paths and real libraries (no injected verifiers, no stubs).
// Honest limits, printed in the report:
//  - the BCH signature comes from an OpenSSL test signer, not a wallet (add tests/fixtures/wallet-bch-signature.json to test a wallet);
//  - the Nostr key is generated by nostr-tools, not a NIP-07 extension (browser/extension steps need a human + real browser).
// A stage is PASS only if it actually ran and succeeded. Missing prerequisites give SKIPPED (never PASS).
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { randomBytes } from 'node:crypto';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const results = [];
const record = (stage, status, detail = '') => {
  results.push({ stage, status, detail });
  console.log(`${status.padEnd(7)} ${stage}${detail ? ' — ' + detail : ''}`);
};
async function stage(name, fn) {
  try {
    const result = await fn();
    if (result?.skip) record(name, 'SKIPPED', result.skip);
    else record(name, 'PASS', result?.detail || '');
    return result?.skip ? 'SKIPPED' : 'PASS';
  } catch (error) {
    record(name, 'FAIL', error?.message || String(error));
    return 'FAIL';
  }
}
const skip = (name, reason) => record(name, 'SKIPPED', reason);
const assert = (condition, message) => { if (!condition) throw new Error(message); };
const packageJson = JSON.parse(fs.readFileSync(path.join(root, 'package.json'), 'utf8'));
const pinned = packageJson.dependencies || {};
const readInstalledPackage = name => {
  try { return JSON.parse(fs.readFileSync(path.join(root, 'node_modules', ...name.split('/'), 'package.json'), 'utf8')); }
  catch { return null; }
};
const installed = {};

// Preflight all runtime dependencies once. Missing/mismatched dependencies are
// recorded as SKIPPED and downstream stages are skipped, avoiding cascaded errors.
for (const [name, expected] of Object.entries(pinned)) {
  const pkg = readInstalledPackage(name);
  installed[name] = Boolean(pkg && pkg.version === expected);
  if (!pkg) skip(`dependency ${name}@${expected}`, 'not installed; run npm install on an internet-connected machine');
  else if (pkg.version !== expected) skip(`dependency ${name}@${expected}`, `installed ${pkg.version}; expected exactly ${expected}`);
  else record(`dependency ${name}@${expected}`, 'PASS', 'exact pinned version installed');
}

let libauth = null;
let nostr = null;
const libauthInstalled = installed['@bitauth/libauth'];
const nostrInstalled = installed['nostr-tools'];
const wsReady = installed.ws;
let libauthReady = false;
let nostrReady = false;

if (libauthInstalled) {
  libauthReady = (await stage('Libauth 2.0.0 import and required API surface', async () => {
    libauth = await import('@bitauth/libauth');
    const required = {
      'secp256k1.recoverPublicKeyCompressed': libauth.secp256k1?.recoverPublicKeyCompressed,
      'secp256k1.recoverPublicKeyUncompressed': libauth.secp256k1?.recoverPublicKeyUncompressed,
      decodeCashAddress: libauth.decodeCashAddress,
      hash160: libauth.hash160,
    };
    const missing = Object.entries(required).filter(([, value]) => typeof value !== 'function').map(([key]) => key);
    assert(missing.length === 0, `missing or incompatible exports: ${missing.join(', ')}`);
    return { detail: 'recovery, CashAddress decoding and HASH160 exports found' };
  })) === 'PASS';
} else {
  skip('Libauth 2.0.0 import and required API surface', 'dependency preflight failed; downstream BCH checks not attempted');
}

if (nostrInstalled) {
  nostrReady = (await stage('nostr-tools 2.10.4 import and required API surface', async () => {
    nostr = await import('nostr-tools');
    for (const name of ['finalizeEvent', 'verifyEvent', 'generateSecretKey', 'getPublicKey']) {
      assert(typeof nostr[name] === 'function', `nostr-tools.${name} is unavailable`);
    }
  })) === 'PASS';
} else {
  skip('nostr-tools 2.10.4 import and required API surface', 'dependency preflight failed; downstream Nostr checks not attempted');
}

const { verifyBchMessageLocal, isLocalBchVerifierAvailable } = await import('../src/bch-local.js');
if (libauthReady) {
  await stage('production BCH verifier loads Libauth', async () => {
    assert(await isLocalBchVerifierAvailable(), 'isLocalBchVerifierAvailable() returned false');
  });
  await stage('production BCH verifier accepts fixtures and rejects tampering', async () => {
    const fixtures = JSON.parse(fs.readFileSync(path.join(root, 'tests/fixtures/bch-signed-messages.json'), 'utf8'));
    for (const fixture of fixtures) {
      assert(await verifyBchMessageLocal({ ...fixture, chain: fixture.chain || (String(fixture.address).startsWith('bchtest:') ? 'chipnet' : 'mainnet') }) === fixture.expectValid, `${fixture.name}: unexpected verification result`);
      assert(await verifyBchMessageLocal({ ...fixture, message: fixture.message + ' ' }) === false, `${fixture.name}: altered message accepted`);
    }
    return { detail: `${fixtures.length} signed-message fixtures` };
  });
} else {
  skip('production BCH verifier loads Libauth', 'Libauth unavailable; no production verifier claim made');
  skip('production BCH verifier accepts fixtures and rejects tampering', 'Libauth unavailable; fixture tests not attempted');
}

await stage('real wallet BCH signature fixture', async () => {
  if (!libauthReady) return { skip: 'Libauth unavailable' };
  const file = path.join(root, 'tests/fixtures/wallet-bch-signature.json');
  if (!fs.existsSync(file)) return { skip: 'no wallet fixture; add {address,message,signature} after signing a test message in a real BCH wallet' };
  const fixture = JSON.parse(fs.readFileSync(file, 'utf8'));
  const chain = fixture.chain || (String(fixture.address).startsWith('bchtest:') ? 'chipnet' : 'mainnet');
  assert(await verifyBchMessageLocal({ ...fixture, chain }), 'wallet-produced signature rejected');
  assert(!(await verifyBchMessageLocal({ ...fixture, chain, message: fixture.message + 'x' })), 'tampered wallet message accepted');
  return { detail: 'wallet-produced signature verified by production Libauth path' };
});

if (nostrReady) {
  await stage('nostr-tools real event signing, verification and tamper rejection', async () => {
    const secretKey = nostr.generateSecretKey();
    const event = nostr.finalizeEvent({ kind: 30078, created_at: Math.floor(Date.now() / 1000), tags: [], content: 'KEYSTONE integration check' }, secretKey);
    assert(nostr.verifyEvent(event) === true, 'valid event rejected');
    // NOTE: nostr-tools caches 'verified' in a hidden Symbol that { ...event } copies, so tamper tests must use a plain JSON clone.
    const clone = () => JSON.parse(JSON.stringify(event));
    assert(nostr.verifyEvent({ ...clone(), content: 'tampered' }) === false, 'tampered content accepted');
    assert(nostr.verifyEvent({ ...clone(), sig: '0'.repeat(128) }) === false, 'invalid signature accepted');
    // The same trap against KEYSTONE's production verifier: an edited SPREAD COPY of a verified event must be rejected.
    const { verifyNostrEvent } = await import('../src/nostr.js');
    const now = Date.now();
    const challenge = { id: 'c-live-check', nostrPubkey: event.pubkey, message: event.content, createdAt: now - 1000, expiresAt: now + 60_000 };
    const proof = nostr.finalizeEvent({ kind: 30078, created_at: Math.floor(now / 1000), tags: [['d', challenge.id], ['keystone', 'identity-proof', 'v1']], content: challenge.message }, secretKey);
    assert((await verifyNostrEvent(proof, challenge)).valid === true, 'KEYSTONE rejected a genuine proof event');
    assert((await verifyNostrEvent({ ...proof, tags: [...proof.tags, ['x', 'y']] }, challenge)).valid === false, 'KEYSTONE accepted an edited copy of a verified event (cached-verification bypass)');
    return { detail: 'real nostr-tools event signing and verification' };
  });
} else {
  skip('nostr-tools real event signing, verification and tamper rejection', 'nostr-tools unavailable');
}

if (nostrReady && wsReady) {
  await stage('nostr-tools SimplePool and Node WebSocket adapter API', async () => {
    const pool = await import('nostr-tools/pool');
    assert(typeof pool.SimplePool === 'function', 'SimplePool export missing');
    assert(typeof pool.useWebSocketImplementation === 'function', 'useWebSocketImplementation export missing');
    const wsModule = await import('ws');
    assert(typeof (wsModule.WebSocket || wsModule.default) === 'function', 'ws WebSocket constructor missing');
  });
} else {
  skip('nostr-tools SimplePool and Node WebSocket adapter API', 'requires exact pinned nostr-tools and ws dependencies');
}

let proofBundle;
let secretKey;
let publicKey;
if (libauthReady && nostrReady) {
  await stage('end-to-end identity binding using production BCH/Nostr verifiers and SQLite', async () => {
    const { SqliteStore } = await import('../src/store-sqlite.js');
    const { createChallenge } = await import('../src/challenges.js');
    const { verifyIdentityBinding } = await import('../src/identity.js');
    const { bchKeypair, signBchMessage } = await import('../tests/helpers/bch-sign.js');
    const store = new SqliteStore(':memory:');
    await store.init();
    secretKey = nostr.generateSecretKey();
    publicKey = nostr.getPublicKey(secretKey);
    const keypair = bchKeypair(`live-${randomBytes(4).toString('hex')}`);
    const challenge = await createChallenge(store, { bchAddress: keypair.address('bchtest'), nostrPubkey: publicKey }, { chain: 'chipnet', challengeTtlSeconds: 300 });
    const nostrEvent = nostr.finalizeEvent({ kind: 30078, created_at: Math.floor(Date.now() / 1000), tags: [['d', challenge.challengeId], ['keystone', 'identity-proof', 'v1'], ['alt', 'KEYSTONE proof']], content: challenge.message }, secretKey);
    const args = { store, challengeId: challenge.challengeId, challengeToken: challenge.challengeToken, bchSignature: signBchMessage(keypair, challenge.message), nostrEvent };
    const wrongKey = await verifyIdentityBinding({ ...args, bchSignature: signBchMessage(bchKeypair('wrong-key'), challenge.message) });
    assert(!wrongKey.ok, 'wrong-key BCH signature accepted');
    const verified = await verifyIdentityBinding(args);
    assert(verified.ok, verified.error || 'identity binding failed');
    assert(!(await verifyIdentityBinding(args)).ok, 'challenge replay accepted');
    proofBundle = (await store.getBinding(verified.binding.id)).proofBundle;
    return { detail: 'OpenSSL-generated BCH test signature; nostr-tools-generated Nostr key (not a real wallet or NIP-07)' };
  });
} else {
  skip('end-to-end identity binding using production BCH/Nostr verifiers and SQLite', 'requires both Libauth and nostr-tools; not attempted');
}

if (proofBundle) {
  await stage('independent proof-bundle verification without database', async () => {
    const { verifyProofBundle } = await import('../src/identity.js');
    const copy = JSON.parse(JSON.stringify(proofBundle));
    assert((await verifyProofBundle(copy)).valid, 'valid proof bundle rejected');
    copy.challenge.chain = 'mainnet';
    assert(!(await verifyProofBundle(copy)).valid, 'tampered proof bundle accepted');
  });
} else {
  skip('independent proof-bundle verification without database', 'upstream production identity-binding stage did not run');
}

if (libauthReady && nostrReady) {
  await stage('MAINNET mode: binding with a bitcoincash: address and a mainnet payment request (no funds, no network)', async () => {
    const { SqliteStore } = await import('../src/store-sqlite.js');
    const { createChallenge } = await import('../src/challenges.js');
    const { verifyIdentityBinding } = await import('../src/identity.js');
    const { createPaymentRequest } = await import('../src/payments.js');
    const { bchKeypair, signBchMessage } = await import('../tests/helpers/bch-sign.js');
    const store = new SqliteStore(':memory:');
    await store.init();
    const sk = nostr.generateSecretKey(), pk = nostr.getPublicKey(sk);
    const keypair = bchKeypair(`mainnet-${randomBytes(4).toString('hex')}`);
    const address = keypair.address('bitcoincash');
    const challenge = await createChallenge(store, { bchAddress: address, nostrPubkey: pk }, { chain: 'mainnet', challengeTtlSeconds: 300 });
    assert(challenge.chain === 'mainnet', 'challenge was not created for mainnet');
    // A Chipnet-prefixed address must be refused by a mainnet server.
    let refused = false; try { await createChallenge(store, { bchAddress: keypair.address('bchtest'), nostrPubkey: pk }, { chain: 'mainnet', challengeTtlSeconds: 300 }); } catch { refused = true; }
    assert(refused, 'mainnet server accepted a Chipnet address');
    const nostrEvent = nostr.finalizeEvent({ kind: 30078, created_at: Math.floor(Date.now() / 1000), tags: [['d', challenge.challengeId], ['keystone', 'identity-proof', 'v1'], ['alt', 'KEYSTONE proof']], content: challenge.message }, sk);
    const verified = await verifyIdentityBinding({ store, challengeId: challenge.challengeId, challengeToken: challenge.challengeToken, bchSignature: signBchMessage(keypair, challenge.message), nostrEvent });
    assert(verified.ok, verified.error || 'mainnet identity binding failed');
    assert(verified.binding.chain === 'mainnet' && verified.binding.bchAddress.startsWith('bitcoincash:'), 'binding is not a mainnet binding');
    const request = await createPaymentRequest(store, { bindingId: verified.binding.id, amountSatoshis: 10_000 }, Date.now(), { chain: 'mainnet', maxSatoshis: 1_000_000 });
    assert(request.uri.startsWith(address + '?amount=0.0001'), 'mainnet payment URI is malformed');
    let capped = false; try { await createPaymentRequest(store, { bindingId: verified.binding.id, amountSatoshis: 1_000_001 }, Date.now(), { chain: 'mainnet', maxSatoshis: 1_000_000 }); } catch { capped = true; }
    assert(capped, 'safety cap not enforced');
    return { detail: 'OpenSSL test signer on a mainnet-format address. No funds moved. This does NOT prove a real wallet or a real mainnet payment.' };
  });
} else {
  skip('MAINNET mode: binding with a bitcoincash: address and a mainnet payment request (no funds, no network)', 'requires both Libauth and nostr-tools; not attempted');
}

const relays = (process.env.LIVE_RELAYS || '').split(',').map(value => value.trim()).filter(Boolean);
if (proofBundle && nostrReady && wsReady && relays.length) {
  await stage('live Nostr relay publish, discovery and retrieved-event verification', async () => {
    const { publishToRelays, discoverFromRelays } = await import('../src/relays.js');
    const { validateRegistryEvent } = await import('../src/registry.js');
    const registryEvent = nostr.finalizeEvent({ kind: 30078, created_at: Math.floor(Date.now() / 1000), tags: [['d', `keystone-binding:${proofBundle.bindingId}`], ['t', 'keystone-binding'], ['alt', 'KEYSTONE binding']], content: JSON.stringify({ protocol: 'KEYSTONE-NOSTR-REGISTRY-v1', proofBundle }) }, secretKey);
    const published = await publishToRelays(registryEvent, relays, { timeoutMs: 15_000 });
    assert(published.ok, `no relay accepted event: ${JSON.stringify(published.failed)}`);
    let found = [];
    for (let attempt = 0; attempt < 5 && !found.length; attempt++) {
      await new Promise(resolve => setTimeout(resolve, 2000));
      found = (await discoverFromRelays(publicKey, relays, { timeoutMs: 15_000 })).events.filter(event => event.id === registryEvent.id);
    }
    assert(found.length > 0, 'published event not retrievable within approximately 10 seconds');
    const verified = await validateRegistryEvent(found[0]);
    assert(verified.valid, verified.error || 'retrieved registry event failed validation');
    return { detail: `published to ${published.published.length}/${relays.length} relays and independently retrieved/verified` };
  });
} else {
  const reason = !proofBundle ? 'production binding not available' : !nostrReady || !wsReady ? 'nostr-tools/ws dependencies unavailable' : 'LIVE_RELAYS not set';
  skip('live Nostr relay publish, discovery and retrieved-event verification', reason);
}

const failed = results.filter(result => result.status === 'FAIL').length;
const skipped = results.filter(result => result.status === 'SKIPPED').length;
const passed = results.filter(result => result.status === 'PASS').length;
const report = {
  generatedAt: new Date().toISOString(),
  version: packageJson.version,
  node: process.version,
  summary: { passed, failed, skipped },
  limits: [
    'BCH signature uses a deterministic test signer unless a real wallet fixture is supplied.',
    'Nostr key is generated by nostr-tools, not a NIP-07 browser extension.',
    'WizardConnect pairing and browser wallet interactions are not covered by this script.'
  ],
  results
};
fs.writeFileSync(path.join(root, 'live-integration-report.json'), JSON.stringify(report, null, 2));
console.log(`\n${passed} passed, ${failed} failed, ${skipped} skipped. Report: live-integration-report.json`);
// 0 = all attempted stages passed; 1 = a real attempted check failed; 2 = blocked/incomplete.
process.exit(failed ? 1 : skipped ? 2 : 0);
